    internal static string StateRoot(string role,string target){return role=="plugin"?Child(target,"data/obs-plugins/obs-playing-next/setup"):Child(target,"setup");}
    internal static void Closed(string role){foreach(string n in role=="plugin"?new[]{"obs64","obs32","obs"}:new[]{"obs-playing-companion"}){var ps=Process.GetProcessesByName(n);bool any=ps.Length>0;foreach(var p in ps)p.Dispose();if(any)throw new IOException("Cierra "+(role=="plugin"?"OBS Studio":"Companion")+" antes de continuar.");}}
    internal static void Validate(string role,string target){if(role!="plugin"&&role!="companion")throw new ArgumentException("Rol inválido");Safe(target);if(role=="plugin"){string exe=Child(target,"bin/64bit/obs64.exe");if(!File.Exists(exe))throw new IOException("Selecciona la carpeta de OBS Studio x64.");var v=FileVersionInfo.GetVersionInfo(exe);if(v.FileMajorPart!=32)throw new IOException("Se requiere OBS Studio 32.x Windows x64.");using(var s=File.OpenRead(exe))using(var r=new BinaryReader(s)){s.Position=0x3c;int offset=r.ReadInt32();s.Position=offset;if(r.ReadUInt32()!=0x4550||r.ReadUInt16()!=0x8664)throw new IOException("OBS no es AMD64.");}}else if(String.Equals(Full(target),Full(Path.GetPathRoot(target)),StringComparison.OrdinalIgnoreCase))throw new IOException("Destino inválido.");}
