    internal static Dictionary<string,byte[]> Payload(string role){var result=new Dictionary<string,byte[]>(StringComparer.OrdinalIgnoreCase);byte[] archive=Resource(role=="plugin"?"native.zip":"companion.zip");using(var m=new MemoryStream(archive))using(var zip=new ZipArchive(m,ZipArchiveMode.Read))foreach(var entry in zip.Entries){if(entry.FullName.EndsWith("/"))continue;string name=entry.FullName.Replace('/', '\\');Child(Path.GetTempPath(),name);string relative;
