    internal static InstallState ReadState(string role,string target){string p=Child(StateRoot(role,target),"state.json");if(!File.Exists(p))return null;var state=Json.Deserialize<InstallState>(File.ReadAllText(p));if(state==null||state.Product!="OBSPlayingNext"||state.Role!=role||!String.Equals(Full(state.Target),Full(target),StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("Registro de instalación desconocido");var allowed=new HashSet<string>(Payload(role).Keys,StringComparer.OrdinalIgnoreCase);allowed.Add(role=="plugin"?"data\\obs-plugins\\obs-playing-next\\setup\\Uninstall.exe":"setup\\Uninstall.exe");var seen=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(var f in state.Files){Child(target,f.Path);if(!allowed.Contains(f.Path)||!seen.Add(f.Path)||f.Hash==null||f.Hash.Length!=64)throw new InvalidDataException("Registro inválido");if(f.Original!=null){Child(StateRoot(role,target),f.Original);if(f.OriginalHash==null||f.OriginalHash.Length!=64)throw new InvalidDataException("Copia original inválida");}}return state;}
    internal static void Register(string role,string target,bool remove){string key="Software\\Microsoft\\Windows\\CurrentVersion\\Uninstall\\OBSPlayingNext-"+role+"-"+Hash(Encoding.UTF8.GetBytes(Full(target).ToUpperInvariant())).Substring(0,12); if(remove){using(var existing=Registry.CurrentUser.OpenSubKey(key)){if(existing!=null&&!String.Equals(existing.GetValue("InstallLocation") as string,target,StringComparison.OrdinalIgnoreCase))return;}Registry.CurrentUser.DeleteSubKeyTree(key,false);return;}using(var k=Registry.CurrentUser.CreateSubKey(key)){k.SetValue("DisplayName","OBS Playing NEXUS "+(role=="plugin"?"Plugin":"Companion"));k.SetValue("DisplayVersion",Version);k.SetValue("Publisher","OBS NEXUS / DjEmiMas");k.SetValue("InstallLocation",target);k.SetValue("UninstallString","\""+Child(StateRoot(role,target),"Uninstall.exe")+"\" /uninstall /role "+role+" /target \""+target+"\"");k.SetValue("NoModify",1);k.SetValue("NoRepair",1);}}
    internal static void Install(string role,string target,bool registry,int failAfter=0){using(var gate=new System.Threading.Mutex(false,"Local\\OBSPlayingNext-"+Hash(Encoding.UTF8.GetBytes(Full(target).ToUpperInvariant())))){bool locked=false;try{try{locked=gate.WaitOne(0);}catch(System.Threading.AbandonedMutexException){locked=true;}if(!locked)throw new IOException("Otra instalación está utilizando esta carpeta.");InstallCore(role,target,registry,failAfter);}finally{if(locked)gate.ReleaseMutex();}}}
    internal static void InstallCore(string role,string target,bool registry,int failAfter){target=Full(target);Validate(role,target);Closed(role);string root=StateRoot(role,target);var old=ReadState(role,target);var payload=Payload(role);string selfRelative=role=="plugin"?"data\\obs-plugins\\obs-playing-next\\setup\\Uninstall.exe":"setup\\Uninstall.exe";payload[selfRelative]=File.ReadAllBytes(Assembly.GetExecutingAssembly().Location);
        var state=new InstallState{Role=role,Target=target};string generation="backups\\"+DateTime.UtcNow.ToString("yyyyMMdd-HHmmss")+"-"+Guid.NewGuid().ToString("N");var undo=new List<KeyValuePair<string,byte[]>>();
        foreach(var pair in payload){string path=Child(target,pair.Key);var prior=old==null?null:old.Files.FirstOrDefault(f=>String.Equals(f.Path,pair.Key,StringComparison.OrdinalIgnoreCase));if(File.Exists(path)&&prior!=null&&HashFile(path)!=prior.Hash)throw new IOException("Archivo modificado: "+pair.Key+". No se sobrescribirá.");if(prior==null&&File.Exists(path)&&!pair.Key.EndsWith("obs-playing-db.dll",StringComparison.OrdinalIgnoreCase)&&!pair.Key.EndsWith("obs-playing-next.dll",StringComparison.OrdinalIgnoreCase)&&!pair.Key.EndsWith("qschannelbackend.dll",StringComparison.OrdinalIgnoreCase))throw new IOException("Destino ocupado por un archivo ajeno: "+pair.Key);}
