        byte[] oldState=File.Exists(Child(root,"state.json"))?File.ReadAllBytes(Child(root,"state.json")):null;
        try{int count=0;foreach(var pair in payload){string path=Child(target,pair.Key);byte[] before=File.Exists(path)?File.ReadAllBytes(path):null;undo.Add(new KeyValuePair<string,byte[]>(path,before));var prior=old==null?null:old.Files.FirstOrDefault(f=>String.Equals(f.Path,pair.Key,StringComparison.OrdinalIgnoreCase));string original=prior==null?null:prior.Original;string originalHash=prior==null?null:prior.OriginalHash;if(before!=null){string backup=generation+"\\"+pair.Key;Atomic(Child(root,backup),before);if(prior==null){original=backup;originalHash=Hash(before);}}Atomic(path,pair.Value);if(HashFile(path)!=Hash(pair.Value))throw new IOException("Checksum de escritura incorrecto");state.Files.Add(new OwnedFile{Path=pair.Key,Hash=Hash(pair.Value),Original=original,OriginalHash=originalHash});if(failAfter>0&&++count==failAfter)throw new IOException("Injected rollback test");}
