    internal static List<string> Uninstall(string role,string target,bool registry){using(var gate=new System.Threading.Mutex(false,"Local\\OBSPlayingNext-"+Hash(Encoding.UTF8.GetBytes(Full(target).ToUpperInvariant())))){bool locked=false;try{try{locked=gate.WaitOne(0);}catch(System.Threading.AbandonedMutexException){locked=true;}if(!locked)throw new IOException("Otra instalación está utilizando esta carpeta.");return UninstallCore(role,target,registry);}finally{if(locked)gate.ReleaseMutex();}}}
    internal static List<string> UninstallCore(string role,string target,bool registry){target=Full(target);Closed(role);Safe(target);var state=ReadState(role,target);var kept=new List<string>();if(state==null)return kept;string root=StateRoot(role,target);
