    }
}

internal static class Elevation {
    internal static bool CanRequest(string role){using(var identity=System.Security.Principal.WindowsIdentity.GetCurrent())return role=="plugin"&&!new System.Security.Principal.WindowsPrincipal(identity).IsInRole(System.Security.Principal.WindowsBuiltInRole.Administrator);}
    internal static ProcessStartInfo Command(string role,string target,bool remove,string log){
        if(role!="plugin")throw new ArgumentException("La instalación de Companion es por usuario.");
        Engine.Safe(target);
        return new ProcessStartInfo(Assembly.GetExecutingAssembly().Location,(remove?"/uninstall":"/install")+" /role plugin /target \""+Engine.Full(target)+"\" /elevated /log \""+log+"\""){UseShellExecute=true,Verb="runas"};
    }
    internal static void Execute(string role,string target,bool remove){
        string log=Path.Combine(Path.GetTempPath(),"OBSPlayingNEXUS-elevated-"+Guid.NewGuid().ToString("N")+".txt");
        try{using(var child=Process.Start(Command(role,target,remove,log))){while(!child.WaitForExit(100))Application.DoEvents();if(child.ExitCode!=0){string message=File.Exists(log)?File.ReadLines(log).FirstOrDefault():null;if(message!=null&&message.Contains(": "))message=message.Substring(message.IndexOf(": ")+2);throw new IOException(message??"No se pudo completar la operación con permisos de administrador.");}}}
        finally{try{if(File.Exists(log))File.Delete(log);}catch(IOException){}catch(UnauthorizedAccessException){}}
    }
}

