}
internal static class Program {
    static string Arg(string[] args,string key,string fallback=null){int i=Array.IndexOf(args,key);return i>=0&&i+1<args.Length?args[i+1]:fallback;}
    static int Error(string[] args,Exception ex){string log=Arg(args,"/log");if(log!=null)File.WriteAllText(log,ex.ToString());else MessageBox.Show(ex.Message,"OBS Playing NEXUS");return 1;}
    [STAThread] static int Main(string[] args){AppContext.SetSwitch("Switch.System.IO.UseLegacyPathHandling",false);AppContext.SetSwitch("Switch.System.IO.BlockLongPaths",false);try{string parent=Arg(args,"/wait-parent");if(parent!=null){try{using(var p=Process.GetProcessById(Int32.Parse(parent))){if(!p.WaitForExit(10000))throw new IOException("El desinstalador anterior sigue abierto.");}}catch(ArgumentException){}}Application.EnableVisualStyles();if(args.Contains("/preview")){using(var form=new Wizard()){form.Show();Application.DoEvents();using(var image=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));image.Save(Arg(args,"/preview"));}form.Close();}return 0;}
        string role=Arg(args,"/role","plugin"),target=Arg(args,"/target");if(args.Contains("/install")){Engine.Install(role,target,!args.Contains("/no-registry"));return 0;}
        if(args.Contains("/uninstall")){string location=Assembly.GetExecutingAssembly().Location;if(location.StartsWith(Engine.StateRoot(role,target)+"\\",StringComparison.OrdinalIgnoreCase)){string temp=Path.Combine(Path.GetTempPath(),"OBSPlayingNext-uninstall-"+Guid.NewGuid().ToString("N")+".exe");File.Copy(location,temp);string log=Arg(args,"/log");Process.Start(new ProcessStartInfo(temp,"/uninstall /role "+role+" /target \""+target+"\" /wait-parent "+Process.GetCurrentProcess().Id+(args.Contains("/no-registry")?" /no-registry":"")+(log!=null?" /log \""+log+"\"":"")){UseShellExecute=true});return 0;}var kept=Engine.Uninstall(role,target,!args.Contains("/no-registry"));if(!args.Contains("/no-registry"))MessageBox.Show("Desinstalación terminada. Archivos modificados conservados: "+kept.Count,"OBS Playing NEXUS");return 0;}
        Application.Run(new Wizard());return 0;
    }catch(UnauthorizedAccessException ex){if(!args.Contains("/elevated")&&!args.Contains("/no-registry")&&Arg(args,"/target")!=null&&(args.Contains("/install")||args.Contains("/uninstall"))&&Elevation.CanRequest(Arg(args,"/role","plugin"))){try{Elevation.Execute("plugin",Arg(args,"/target"),args.Contains("/uninstall"));return 0;}catch(Exception failure){return Error(args,failure);}}return Error(args,ex);}catch(Exception ex){return Error(args,ex);}}
}
